package com.b5.vpn;
import android.content.Context;import android.location.*;import android.os.SystemClock;
public final class MockGps {private final LocationManager manager;private boolean installed=false;public MockGps(Context c){manager=(LocationManager)c.getSystemService(Context.LOCATION_SERVICE);}public void update(){if(!installed){manager.addTestProvider(LocationManager.GPS_PROVIDER,false,false,false,false,true,true,true,android.location.provider.ProviderProperties.POWER_USAGE_LOW,android.location.provider.ProviderProperties.ACCURACY_FINE);manager.setTestProviderEnabled(LocationManager.GPS_PROVIDER,true);installed=true;}Location l=new Location(LocationManager.GPS_PROVIDER);l.setLatitude(40.7128);l.setLongitude(-74.0060);l.setAccuracy(3);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());manager.setTestProviderLocation(LocationManager.GPS_PROVIDER,l);}public void stop(){if(installed){try{manager.removeTestProvider(LocationManager.GPS_PROVIDER);}catch(Exception ignored){}installed=false;}}}
